def T(rows):
    o = ['<table header-row="true" fit-page-width="true">']
    for r in rows:
        o.append("\t<tr>"); o += [f"\t\t<td>{c}</td>" for c in r]; o.append("\t</tr>")
    o.append("</table>"); return "\n".join(o)
def code(lang, body): return f"\n```{lang}\n{body}\n```\n"
def Q(q, a): return f"<details>\n<summary>{q}</summary>\n\t{a}\n</details>"
def goal(icon, text): return f'<callout icon="{icon}" color="blue_bg">\n\t{text}\n</callout>'
def road(n, name):
    steps = ["0 VPC 입구", "1 HTTP 기초", "2 TLS 종료 지점", "3 ALB 해부", "4 오리진 보호(헤더)", "5 헬스체크", "6 Apache 프록시", "7 분산·타임아웃", "8 WEB 관측", "9 장애 모드", "10 ASG·AMI"]
    steps[n] = f"**{steps[n]}(이 페이지)**"
    return f'<callout icon="🗺️" color="gray_bg">\n\t**로드맵 위치**: {" → ".join(steps)}.\n</callout>'
