   ("ssl_cipher · ssl_protocol", "`TLS_AES_128_GCM_SHA256 TLSv1.3`", "2단계의 실물"),
   ("trace_id", "`Root=1-6aab51f9-…`", "X-Ray 추적 ID · Apache 로그와 대조 가능"),
